import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.NavigableMap;
import java.util.PriorityQueue;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;

public class Main {
    // --- HashSet 去重：依赖 equals + hashCode ---
    static final class User {
        final int id;
        final String name;
        User(int id, String name) { this.id = id; this.name = name; }
        // 基于 id 判等
        public boolean equals(Object o) {
            return o instanceof User other && id == other.id;
        }
        public int hashCode() { return Integer.hashCode(id); }
        public String toString() { return name + "#" + id; }
    }

    // --- TreeSet 比较去重：依赖 Comparator ---
    static final class Student {
        final String name;
        final int age;
        Student(String name, int age) { this.name = name; this.age = age; }
        public String toString() { return name + ":" + age; }
    }

    // --- LinkedHashMap 实现简单 LRU ---
    static final class LruCache<K, V> extends LinkedHashMap<K, V> {
        private final int maxSize;
        LruCache(int maxSize) {
            super(16, 0.75f, true); // accessOrder = true
            this.maxSize = maxSize;
        }
        protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
            return size() > maxSize; // 超容量时移除最久未访问
        }
    }

    public static void main(String[] args) {
        // HashSet：两个 User 同 id，去重后 size=1
        Set<User> users = new HashSet<>();
        users.add(new User(1, "Alice"));
        users.add(new User(1, "Alice-v2"));
        System.out.println("HashSet size by id: " + users.size());
        assert users.size() == 1;

        // TreeSet：按 age 比较，两个 age=18 的 Student 被视为重复
        TreeSet<Student> byAge = new TreeSet<>(Comparator.comparingInt(s -> s.age));
        byAge.add(new Student("Tom", 18));
        byAge.add(new Student("Jerry", 18));
        byAge.add(new Student("Ada", 20));
        System.out.println("TreeSet by age (size=2): " + byAge);
        assert byAge.size() == 2; // Tom/Jerry 只保留一个

        // TreeMap：有序 key + 范围查询
        NavigableMap<String, Integer> scores = new TreeMap<>();
        scores.put("alice", 90);
        scores.put("bob", 80);
        scores.put("carol", 95);
        scores.put("dave", 70);
        System.out.println("TreeMap range [bob,dave): " + scores.subMap("bob", true, "dave", false));

        // LRU：访问 a 后再插入 d，最久未访问的 b 被淘汰
        LruCache<String, Integer> cache = new LruCache<>(3);
        cache.put("a", 1);
        cache.put("b", 2);
        cache.put("c", 3);
        cache.get("a");          // 访问 a，a 移到链表尾部
        cache.put("d", 4);       // 超容量，移除链表头部的 b
        System.out.println("LRU keys after evict: " + cache.keySet());
        assert !cache.containsKey("b");

        // PriorityQueue：连续 poll 才按优先级输出
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        pq.addAll(List.of(3, 1, 2));
        ArrayList<Integer> pollOrder = new ArrayList<>();
        while (!pq.isEmpty()) pollOrder.add(pq.poll());
        System.out.println("PriorityQueue poll order: " + pollOrder);
        assert pollOrder.equals(List.of(1, 2, 3));

        // ArrayDeque：两端操作 O(1)
        ArrayDeque<String> deque = new ArrayDeque<>();
        deque.addFirst("front");
        deque.addLast("back");
        System.out.println("Deque: " + deque.removeFirst() + ", " + deque.removeLast());
    }
}
